    H,W=len(I),len(I[0])
    O=[[0]*W for _ in range(H)]
    bar=[i for i in range(H) if any(x!=0 for x in I[i])]
    r0=bar[0]
    bpos={j:I[r0][j] for j in range(W) if I[r0][j]!=0}
    cpos={v:j for j,v in bpos.items()}
    singles={}
    for i in range(H):
        for j in range(W):
            if I[i][j]!=0 and i!=r0 and j not in bpos:
                singles.setdefault(I[i][j],[]).append((i,j))
    for j in range(W):
        if j in bpos: O[r0][j]=bpos[j]
    for v,s in singles.items():
        i0,j0=s[0]
        # vertical from bar down to singleton row
        for k in range(r0,i0+1): O[k][cpos[v]]=v
        # horizontal from bar column to singleton
        for k in range(min(cpos[v],j0), max(cpos[v],j0)+1): O[i0][k]=v
    # colors with no singleton: vertical full height
    for v,j in bpos.items():
        if v not in singles:
            for k in range(r0,H): O[k][j]=v
    return O
